	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// pathBarLabel prefixes the target field in the bar.
const pathBarLabel = "Target › "

// pathColumns describes the hops table. Plain text in Cell, colour in Style
// (Rule 122). A silent hop is dim, never red: it is not a failure.
func pathColumns() []datatable.Column[nettrace.Hop] {
	hop := datatable.Column[nettrace.Hop]{
		Title: "Hop", Sizing: datatable.SizingFixed, MinWidth: 3,
		Cell: func(h nettrace.Hop) string { return strconv.Itoa(h.TTL) },
	}
	answer := datatable.Column[nettrace.Hop]{
		Title: "Answer", Sizing: datatable.SizingFixed, MinWidth: 11,
		Cell:  func(h nettrace.Hop) string { return h.Kind.String() },
		Style: pathAnswerStyle,
	}
	address := datatable.Column[nettrace.Hop]{
		Title: "Address", Sizing: datatable.SizingContent, MinWidth: 15, Flex: 1,
		Cell: func(h nettrace.Hop) string {
			if !h.Addr.IsValid() {
				return "-"
			}
			return h.Addr.String()
		},
		Style: func(h nettrace.Hop) lipgloss.Style {
			if !h.Addr.IsValid() {
				return theme.DimStyle
			}
			return lipgloss.Style{}
		},
	}
	rtt := datatable.Column[nettrace.Hop]{
		Title: "RTT", Sizing: datatable.SizingFixed, MinWidth: 9,
		Cell: func(h nettrace.Hop) string {
			if h.RTT <= 0 {
				return "-"
			}
			return fmt.Sprintf("%.1f ms", float64(h.RTT)/float64(time.Millisecond))
		},
		Style: func(h nettrace.Hop) lipgloss.Style {
			if h.RTT <= 0 {
				return theme.DimStyle
			}
			return lipgloss.Style{}
		},
	}
	return []datatable.Column[nettrace.Hop]{hop, answer, address, rtt}
}

func pathAnswerStyle(h nettrace.Hop) lipgloss.Style {
	switch h.Kind {
	case nettrace.HopSilent, nettrace.HopUnresolved:
		return theme.DimStyle
	case nettrace.HopError:
		return theme.SeverityTextStyle("MEDIUM")
	}
	return lipgloss.Style{}
}

// view renders the table; the body is never replaced (Rule 139).
func (pm *PathModel) view() string { return pm.table.View() }

// barView is the target field in its frame, two lines in every state.
func (pm *PathModel) barView(width int) string {
	return components.BarFrame(width, theme.KeyStyle.Render(pathBarLabel)+pm.input.View())
}

// statusLine is derived on every frame (Rule 128).
func (pm *PathModel) statusLine() components.Status {
	if pm.errText != "" {
		return components.Status{Text: pm.errText, Level: components.LevelError}
	}
	if pm.state != pathRunning {
		return components.Status{}
	}
	host := pm.target.Host
	n := len(pm.table.Items())
	if !pm.addr.IsValid() && n == 0 {
		return components.Status{Text: "Resolving " + host + "...", Activity: true}
	}
	where := host
	if pm.addr.IsValid() && pm.addr.String() != host {
		where += " (" + pm.addr.String() + ")"
	}
	noun := "hops"
	if n == 1 {
		noun = "hop"
	}
	return components.Status{
		Text:     fmt.Sprintf("Tracing %s — %d %s answered", where, n, noun),
		Activity: true,
	}
}

// headerInfo lists the target and, once a run ended, how it ended.
func (pm *PathModel) headerInfo() []shortcut.HeaderInfo {
	var out []shortcut.HeaderInfo
	if pm.target.Host != "" {
		value := pm.target.String()
		if pm.addr.IsValid() && pm.addr.String() != pm.target.Host {
			value += " (" + pm.addr.String() + ")"
		}
		out = append(out, shortcut.HeaderInfo{Key: "Target", Value: value, Style: theme.HeaderValueStyle})
	}
	if pm.result != nil {
		out = append(out, shortcut.HeaderInfo{Key: "Path", Value: pathOutcomeLabel(*pm.result), Style: theme.HeaderValueStyle})
	}
	return out
}

// shortcuts: the running mode replaces the list, the other states grey out
// (Rule 130).
func (pm *PathModel) shortcuts() shortcut.Shortcuts {
	off := !pm.launchable().Enabled()
	switch pm.state {
	case pathRunning:
		return shortcut.Shortcuts{{Key: "esc", Description: "Cancel the trace"}}
	case pathDone:
		return shortcut.Shortcuts{
			{Key: "tab", Description: "Switch tab"},
			{Key: "enter", Description: "Trace again", Disabled: off},
			{Key: "esc", Description: "Edit the target"},
			{Key: "?", Description: "Help"},
		}
	}
	return shortcut.Shortcuts{
		{Key: "tab", Description: "Switch tab"},
		{Key: "enter", Description: "Trace the path", Disabled: off},
	}
}
package netdiag

import (
	"errors"
	"fmt"
	"slices"
	"strconv"
	"strings"

	"github.com/anthnel/devdesk/internal/nettrace"
)

var (
	// errPathResolve marks a target name that could not be resolved.
	errPathResolve = errors.New("could not resolve the path target")
	// errPathNoIPv4 marks a target name that resolved to no IPv4 address.
	errPathNoIPv4 = errors.New("the path target has no IPv4 address")
	// errPathIPv6 is the validation message for a literal IPv6 target. It is
	// shown as is in the footer, hence the capital letter.
	errPathIPv6 = errors.New( //nolint:staticcheck // ST1005: user-facing text, same wording as pathErrorLabel
		"Only IPv4 targets are supported by the path trace")
)

// pathTarget is the validated input of the path trace. Port is optional (0 =
// none); it is shown but does not change the probes.
type pathTarget struct {
	Host string
	Port int
}

// String renders the target as typed: "host" or "host:port".
func (t pathTarget) String() string {
	if t.Port == 0 {
		return t.Host
	}
	return t.Host + ":" + strconv.Itoa(t.Port)
}

// parsePathTarget validates "host" or "host:port". IPv6 literals are refused.
func parsePathTarget(input string) (pathTarget, error) {
	s := strings.TrimSpace(input)
	if s == "" {
		return pathTarget{}, errors.New("target is required")
	}
	// Brackets or several colons can only be an IPv6 literal.
	if strings.Contains(s, "[") || strings.Count(s, ":") > 1 {
		return pathTarget{}, errPathIPv6
	}
	host, portText, hasPort := strings.Cut(s, ":")
	if err := validateTarget(host); err != nil {
		return pathTarget{}, err
	}
	if !hasPort {
		return pathTarget{Host: host}, nil
	}
	if err := validatePort(portText); err != nil {
		return pathTarget{}, err
	}
	port, _ := strconv.Atoi(portText) // validatePort accepted it
	return pathTarget{Host: host, Port: port}, nil
}

// visiblePathHops returns a new slice of the hops to display: sorted by TTL,
// unresolved hops dropped, everything above the first target or unreachable
// hop cut. The input is left untouched.
func visiblePathHops(hops []nettrace.Hop) []nettrace.Hop {
	sorted := slices.Clone(hops)
	slices.SortStableFunc(sorted, func(a, b nettrace.Hop) int { return a.TTL - b.TTL })
	out := make([]nettrace.Hop, 0, len(sorted))
	for _, h := range sorted {
		if h.Kind == nettrace.HopUnresolved {
			continue
		}
		out = append(out, h)
		if h.Kind == nettrace.HopTarget || h.Kind == nettrace.HopUnreachable {
			break
		}
	}
	return out
}

// pathErrorLabel maps a trace error to a fixed footer sentence. It never
// carries the raw error text (errno, resolver message).
func pathErrorLabel(host string, err error) string {
	switch {
	case errors.Is(err, errPathResolve):
		return "Could not resolve " + host + " — no probe was sent"
	case errors.Is(err, errPathNoIPv4):
		return host + " has no IPv4 address — the path trace is IPv4 only"
	case errors.Is(err, nettrace.ErrNotIPv4):
		return "Only IPv4 targets are supported by the path trace"
	case errors.Is(err, nettrace.ErrNotUnicast):
		return "The path trace needs a unicast address"
	case errors.Is(err, nettrace.ErrNoRoute):
		return "No route to " + host + " from this machine — no probe was sent"
	case errors.Is(err, nettrace.ErrUnsupported):
		return "The path trace is not supported on this platform"
	}
	return "The path trace failed — check logs"
}

// pathOutcomeLabel describes how a finished trace ended; N is the number of
// hops in the result.
func pathOutcomeLabel(res nettrace.Result) string {
	n := len(res.Hops)
	switch res.Outcome {
	case nettrace.OutcomeReached:
		return fmt.Sprintf("Reached at hop %d", n)
	case nettrace.OutcomeUnreachable:
		return fmt.Sprintf("Reported unreachable at hop %d", n)
	case nettrace.OutcomeMaxHops:
		return fmt.Sprintf("No answer from the target within %d hops", n)
	case nettrace.OutcomeDeadline:
		return fmt.Sprintf("Stopped after %d s", int(nettrace.DeadlineLimit.Seconds()))
	case nettrace.OutcomeCancelled:
		return "Canceled"
	}
	return "The path trace ended"
}
